classdef NarxTest < matlab.unittest.TestCase
%NARXTEST  Analytic, property and error tests for rid.rep.Narx.
%
%   Layers 1 and 2 of the project's test plan. The load-bearing tests are the hand-computed
%   regressor matrices and the warm-up boundary: an off-by-one in the lag indexing
%   shifts every coordinate by one sample, which no aggregate check would notice --
%   J would simply be slightly wrong forever. So the expected matrices here are
%   written out by hand, never generated by
%   the code under test.
%
%   The signals are deliberately non-uniform (u has a non-constant difference,
%   y is an order of magnitude larger) so that a swapped column, a swapped lag or a
%   confusion between u and y cannot pass.

    properties (Constant)
        U    = [1; 2; 4; 7; 11; 16]     % du = 1 2 3 4 5, all distinct
        Y    = [10; 20; 30; 40; 50; 60]
        Tol  = 1e-12
    end

    methods (Access = private)
        function hist = history(tc)
            hist = wellFormedHistory(tc.U, "y", tc.Y, "tS", 0.1);
        end
    end

    methods (Test)

        % --- construction and the derived sizes ------------------------------

        function oneDeclarationPerDimension(tc)
            % every dimension carries its own declared bounds, so
            % requiredNames has exactly nDim entries -- not one per signal.
            rep = rid.rep.Narx(3, 2, "nInputs", 2, "inputDifference", false);
            tc.verifyEqual(rep.nDim, 2 * 3 + 2);
            tc.verifyEqual(numel(rep.requiredNames()), rep.nDim);
        end

        function coordinateNamesCarryTheLagNotAnOrdinal(tc)
            % The lag is IN the name, so changing nk changes WHICH names are
            % required. An ordinal scheme would leave "u1" meaning u(k) at nk = 0
            % and u(k-1) at nk = 1, silently rebinding a stale declaration to a
            % different lag.
            tc.verifyEqual(rid.rep.Narx(2, 1, "nk", 0, "inputDifference", false ...
                ).requiredNames(), ["u1_k" "u1_km1" "y_km1"]);
            tc.verifyEqual(rid.rep.Narx(2, 1, "nk", 1, "inputDifference", false ...
                ).requiredNames(), ["u1_km1" "u1_km2" "y_km1"]);
            % The default coordinates: [u(k), du(k), yHat(k-1)].
            tc.verifyEqual(rid.rep.Narx(2, 1).requiredNames(), ...
                ["u1_k" "du1_k" "y_km1"]);
        end

        % --- coordinateInfo: the meaning of a coordinate, as data ----

        function everyCoordinateCarriesItsKindChannelAndLag(tc)
            % The default coordinates, stated as data rather than as names.
            info = rid.rep.Narx(2, 1).coordinateInfo();
            tc.verifyEqual([info.name],    ["u1_k" "du1_k" "y_km1"]);
            tc.verifyEqual([info.kind],    ["inputLevel" "inputDifference" "output"]);
            tc.verifyEqual([info.channel], [1 1 NaN]);
            tc.verifyEqual([info.lag],     [0 0 1]);
        end

        function theLagIsTheTrueLagAndIsNotBoundedByNDim(tc)
            % The reason coordinateInfo exists. With nk = 2 and nLagY = 0 the lags
            % are 2 and 3 while nDim is 2, so any consumer that searched lags
            % 0:nDim would miss u1_km3 -- which is exactly what +gen did.
            rep  = rid.rep.Narx(2, 0, "nk", 2, "inputDifference", false);
            info = rep.coordinateInfo();
            tc.verifyEqual(rep.nDim, 2);
            tc.verifyEqual([info.name], ["u1_km2" "u1_km3"]);
            tc.verifyEqual([info.lag],  [2 3]);
            tc.verifyTrue(all([info.lag] > rep.nDim - 1));
            tc.verifyEqual([info.kind], ["inputLevel" "inputLevel"]);
        end

        function theFi17VariantIsRepresentable(tc)
            % [u(k-1), y(k-1)]: nk = 1 with no difference basis, one of three
            % candidate variants. It must classify as two input levels and an output,
            % not be rejected for having nk > 0.
            rep  = rid.rep.Narx(1, 1, "nk", 1, "inputDifference", false);
            info = rep.coordinateInfo();
            tc.verifyEqual([info.name],    ["u1_km1" "y_km1"]);
            tc.verifyEqual([info.kind],    ["inputLevel" "output"]);
            tc.verifyEqual([info.channel], [1 NaN]);
            tc.verifyEqual([info.lag],     [1 1]);
        end

        function narxHasNoStateCoordinates(tc)
            % "state" belongs to the shared closed set for the StateSpace; a
            % NARX representation never emits one.
            info = rid.rep.Narx(3, 2, "nInputs", 2).coordinateInfo();
            tc.verifyFalse(any([info.kind] == "state"));
        end

        function theNamingConventionLivesInOnePlace(tc)
            % +gen matches a du<X>_k admissible bound to a rate limit and
            % +viz renders these names; both need the convention, and a
            % second spelling of it would be a second name.
            tc.verifyEqual(rid.rep.Narx.coordinateName("u1", 0),  "u1_k");
            tc.verifyEqual(rid.rep.Narx.coordinateName("du2", 3), "du2_km3");
            tc.verifyEqual(rid.rep.Narx.coordinateName("y", 1),   "y_km1");
        end

        function warmupIsTheDeepestLagOfEitherSignal(tc)
            tc.verifyEqual(rid.rep.Narx(2, 1, "inputDifference", false).nWarmup, 1);
            tc.verifyEqual(rid.rep.Narx(1, 4, "inputDifference", false).nWarmup, 4);
            tc.verifyEqual(rid.rep.Narx(3, 1, "nk", 2, "inputDifference", false).nWarmup, 4);
        end

        function differenceBasisLeavesNDimAndWarmupUnchanged(tc)
            % This is what makes the comparison a comparison of GEOMETRY
            % rather than of size: the difference basis is a change of basis of the
            % input block, not a bigger or smaller space.
            withLags = rid.rep.Narx(2, 1, "inputDifference", false);
            withDiff = rid.rep.Narx(2, 1, "inputDifference", true);
            tc.verifyEqual(withDiff.nDim,    withLags.nDim);
            tc.verifyEqual(withDiff.nWarmup, withLags.nWarmup);
        end

        function inputDifferenceIsNeverASilentNoOp(tc)
            % With a single input coordinate there is no difference to form;
            % accepting the flag would let a configuration mean something other
            % than what it says.
            tc.verifyError(@() rid.rep.Narx(1, 1, "inputDifference", true), ...
                "rid:rep:invalidRepresentation");
        end

        function minHorizonIsTheFirstRowThatContainsTheAppliedInput(tc)
            % The input block starts at u(k-nk), so the sample about to be
            % applied, u(N+1), first appears in the regressor row at k = N+1+nk.
            % With nHorizon <= nk NO scored point depends on it: J is constant in
            % the applied sample, the optimizer returns whatever its start held,
            % and an arbitrary input is committed without an error. nHorizon has
            % no default, so nothing else stopped a run from choosing 1.
            %
            % Fails if: Narx returns the inherited 1, or reads nLagU/nLagY, which
            % do not move the first row containing u(N+1).
            for nk = 0:2
                rep = rid.rep.Narx(2, 1, "nk", nk, "inputDifference", false);
                tc.verifyEqual(rep.minHorizon(), nk + 1, ...
                    sprintf("nk = %d", nk));
            end
            % The lag orders are irrelevant to the floor: they deepen the WARM-UP,
            % which is where the window starts, not where u(N+1) first appears.
            % Only nk moves the floor.
            deep = rid.rep.Narx(1, 5, "nk", 1, "inputDifference", false);
            tc.verifyEqual(deep.nWarmup, 5);       % five, from the output lags
            tc.verifyEqual(deep.minHorizon(), 2);  % still nk + 1
        end

        function theHorizonFloorIsConcreteOnTheBaseClassAndDefaultsToOne(tc)
            % WHY THE REPRESENTATION STATES IT: the loop must not branch on
            % a representation class, and only the representation knows where its
            % input block starts. A representation that does not look back inherits
            % 1 and declares nothing -- so `+rhc` never names `nk`, which is a
            % property of this one class.
            tc.verifyEqual(SurrogateDependentRep().minHorizon(), 1);
        end

        function isValueClassNotHandle(tc)
            tc.verifyFalse(isa(rid.rep.Narx(2, 1), "handle"));
        end

        % --- build: hand-computed regressors --------------------------------

        function buildMatchesHandComputedLagVectors(tc)
            % nk = 0, nLagU = 2, nLagY = 1 -> z(k) = [u(k), u(k-1), y(k-1)].
            rep = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", false);
            [Zphys, kIndex] = rep.build(tc.history(), []);

            expected = [ 2  1 10
                         4  2 20
                         7  4 30
                        11  7 40
                        16 11 50];
            tc.verifyEqual(Zphys, expected, "AbsTol", tc.Tol);
            tc.verifyEqual(kIndex, (2:6).');
        end

        function inputDelayShiftsOnlyTheInputBlock(tc)
            % nk = 1 -> z(k) = [u(k-1), u(k-2), y(k-1)]. The OUTPUT lags are always
            % strictly past and are unaffected by nk.
            rep = rid.rep.Narx(2, 1, "nk", 1, "inputDifference", false);
            [Zphys, kIndex] = rep.build(tc.history(), []);

            expected = [ 2  1 20
                         4  2 30
                         7  4 40
                        11  7 50];
            tc.verifyEqual(Zphys, expected, "AbsTol", tc.Tol);
            tc.verifyEqual(kIndex, (3:6).');
        end

        function differenceBasisBuildsLevelThenDifferences(tc)
            % The default coordinates: [u(k), du(k), y(k-1)].
            rep = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", true);
            [Zphys, kIndex] = rep.build(tc.history(), []);

            expected = [ 2 1 10
                         4 2 20
                         7 3 30
                        11 4 40
                        16 5 50];
            tc.verifyEqual(Zphys, expected, "AbsTol", tc.Tol);
            tc.verifyEqual(kIndex, (2:6).');
        end

        function differenceBasisGeneralizesToSuccessiveDifferences(tc)
            % nLagU = 3 -> [u(k), du(k), du(k-1)]. Needed because
            % defaultRepresentation derives nLagU = nStates + 1, so a second-order
            % model asks for three input coordinates.
            rep = rid.rep.Narx(3, 1, "nk", 0, "inputDifference", true);
            [Zphys, kIndex] = rep.build(tc.history(), []);

            expected = [ 4 2 1 20
                         7 3 2 30
                        11 4 3 40
                        16 5 4 50];
            tc.verifyEqual(Zphys, expected, "AbsTol", tc.Tol);
            tc.verifyEqual(kIndex, (3:6).');
        end

        function columnsAreChannelMajorLagMinor(tc)
            % Two inputs: the whole lag block of channel 1, then of channel 2, then
            % the output lags. A repmat/repelem confusion here would interleave the
            % channels and silently pair each coordinate with the wrong bound.
            u2   = [tc.U, 100 * tc.U];
            hist = wellFormedHistory(u2, "y", tc.Y, "tS", 0.1);
            rep  = rid.rep.Narx(2, 1, "nInputs", 2, "inputDifference", false);
            Zphys    = rep.build(hist, []);

            tc.verifyEqual(Zphys(:, 1), tc.U(2:6),         "AbsTol", tc.Tol);
            tc.verifyEqual(Zphys(:, 2), tc.U(1:5),         "AbsTol", tc.Tol);
            tc.verifyEqual(Zphys(:, 3), 100 * tc.U(2:6),   "AbsTol", tc.Tol);
            tc.verifyEqual(Zphys(:, 4), 100 * tc.U(1:5),   "AbsTol", tc.Tol);
            tc.verifyEqual(Zphys(:, 5), tc.Y(1:5),         "AbsTol", tc.Tol);
        end

        % --- the warm-up boundary -----------------------------------

        function warmupRowsAreDroppedNeverPadded(tc)
            % nSteps = nWarmup + 1 gives exactly one row, and it is the row for the
            % LAST sample -- not a padded row for the first.
            rep  = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", false);
            hist = wellFormedHistory([3; 5], "y", [7; 9], "tS", 0.1);
            [Zphys, kIndex] = rep.build(hist, []);
            tc.verifyEqual(Zphys, [5 3 7], "AbsTol", tc.Tol);
            tc.verifyEqual(kIndex, 2);
        end

        function historyShorterThanTheWarmupIsEmptyNotAnError(tc)
            % At the start of every run there genuinely is no complete regressor
            % vector, so the loop must survive this without branching.
            rep = rid.rep.Narx(3, 2, "nk", 1, "inputDifference", false);   % nWarmup = 3
            for nSteps = 1:3
                hist = wellFormedHistory((1:nSteps).', "y", (1:nSteps).', "tS", 0.1);
                [Zphys, kIndex] = rep.build(hist, []);
                tc.verifyEqual(size(Zphys), [0, rep.nDim]);
                tc.verifyEmpty(kIndex);
            end
        end

        function rowCountIsExactlyNStepsMinusWarmup(tc)
            for nLagU = 1:3
                for nLagY = 0:3
                    rep  = rid.rep.Narx(nLagU, nLagY, "inputDifference", false);
                    hist = wellFormedHistory((1:12).', "y", (1:12).', "tS", 0.1);
                    [Zphys, kIndex] = rep.build(hist, []);
                    tc.verifyEqual(size(Zphys, 1), 12 - rep.nWarmup);
                    tc.verifyEqual(kIndex, (rep.nWarmup + 1 : 12).');
                end
            end
        end

        % --- bounds and names ------------------------------------------------

        function boundsIsAnOrderedLookupOverTheDeclaration(tc)
            % no expansion, no inheritance. EIGHT DIFFERENT ranges for eight
            % dimensions, so any lag inheriting its neighbour's range shows up
            % immediately -- a replicated box would repeat rows.
            rep = rid.rep.Narx(3, 2, "nInputs", 2, "inputDifference", false);
            roi = struct("u1_k",   [0 5],   "u1_km1", [0 4],   "u1_km2", [0 3], ...
                         "u2_k",   [-2 2],  "u2_km1", [-2 1],  "u2_km2", [-1 2], ...
                         "y_km1",  [10 30], "y_km2",  [11 29]);
            [box, dimName] = rep.bounds(roi);

            tc.verifyEqual(size(box), [8 2]);
            tc.verifyEqual(box, [0 5; 0 4; 0 3; -2 2; -2 1; -1 2; 10 30; 11 29]);
            tc.verifyEqual(dimName, ["u1_k" "u1_km1" "u1_km2" ...
                                     "u2_k" "u2_km1" "u2_km2" ...
                                     "y_km1" "y_km2"]);
        end

        function perDimensionRangesAreIndependent(tc)
            % The declaration is a flat map, so the box is exactly what was
            % declared, in coordinate order, and nothing links one row to another.
            rep = rid.rep.Narx(4, 1, "inputDifference", false);
            wanted = [-1 1; -2 2; -3 3; -4 4; 0 100];
            names  = rep.requiredNames();
            roi    = struct();
            for iDim = 1:numel(names)
                roi.(names(iDim)) = wanted(iDim, :);
            end
            tc.verifyEqual(rep.bounds(roi), wanted);
        end

        function differenceCoordinatesCarryTheirOwnDeclaredRange(tc)
            % Under the declared-bounds rule this is unremarkable rather than an exception: du is
            % declared because EVERY dimension is declared, and the declared difference range's special
            % pleading for it disappears with the replication rule.
            rep = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", true);
            roi = struct("u1_k", [0 5], "du1_k", [-0.5 0.5], "y_km1", [10 30]);
            [box, dimName] = rep.bounds(roi);

            tc.verifyEqual(box, [0 5; -0.5 0.5; 10 30]);
            tc.verifyEqual(dimName, ["u1_k" "du1_k" "y_km1"]);
        end

        function nLagYZeroDropsTheOutputDeclarationEntirely(tc)
            rep = rid.rep.Narx(2, 0, "inputDifference", false);
            tc.verifyEqual(rep.requiredNames(), ["u1_k" "u1_km1"]);
            [box, dimName] = rep.bounds(struct("u1_k", [0 5], "u1_km1", [0 4]));
            tc.verifyEqual(box, [0 5; 0 4]);
            tc.verifyEqual(dimName, ["u1_k" "u1_km1"]);
        end

        function boundsFeedTheNormalizationDirectly(tc)
            % rep.bounds -> rid.roi.Normalization is the documented seam:
            % the representation owns the expansion, +roi consumes the result.
            rep = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", true);
            roi = struct("u1_k", [0 5], "du1_k", [-0.5 0.5], "y_km1", [10 30]);
            [box, dimName] = rep.bounds(roi);
            nrm = rid.roi.Normalization(box, dimName);
            tc.verifyEqual(nrm.nDim, rep.nDim);
            tc.verifyEqual(nrm.dimName, rep.requiredNames());
            tc.verifyEqual(nrm.toNormalized([5 0.5 30]), [1 1 1], "AbsTol", tc.Tol);
        end

        % --- ROI declaration errors ------------------------------------------

        function aMissingDeclarationErrorsByName(tc)
            rep = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", true);
            roi = struct("u1_k", [0 5], "y_km1", [10 30]);
            tc.verifyError(@() rep.bounds(roi), "rid:rep:missingRange");
            % The identifier is not enough: the specification requires the error to
            % NAME what is missing, so that a wrong declaration is diagnosable
            % without reading the representation's expansion rules.
            tc.verifySubstring(NarxTest.messageOf(@() rep.bounds(roi)), "du1_k");
        end

        function anUnknownDeclarationIsAnError(tc)
            % Precedent the optional-members fields struct: a struct member the consumer does not use is an
            % error, because it is almost always a typo or a declaration meant for
            % a different representation.
            % Kept deliberately under the declared-bounds rule: per-dimension names make typos MORE
            % likely, not less, and an ignored field is exactly the silent
            % acceptance the project forbids.
            rep = rid.rep.Narx(2, 1, "inputDifference", false);
            roi = struct("u1_k", [0 5], "u1_km1", [0 4], "y_km1", [10 30], ...
                         "x1", [0 1]);
            tc.verifyError(@() rep.bounds(roi), "rid:rep:unknownRange");
            tc.verifySubstring(NarxTest.messageOf(@() rep.bounds(roi)), "x1");
        end

        function aMissingLagRangeIsNotInheritedFromAnotherLag(tc)
            % The test that pins the declared-bounds rule's removal of replication: u1_km1 is absent,
            % and the correct behaviour is to say so -- NOT to reuse u1_k's range.
            rep = rid.rep.Narx(2, 1, "inputDifference", false);
            roi = struct("u1_k", [0 5], "y_km1", [10 30]);

            tc.verifyError(@() rep.bounds(roi), "rid:rep:missingRange");
            tc.verifySubstring(NarxTest.messageOf(@() rep.bounds(roi)), "u1_km1");

            % ... and once declared, its range is its own and differs from u1_k's.
            roi.u1_km1 = [-7 -3];
            tc.verifyEqual(rep.bounds(roi), [0 5; -7 -3; 10 30]);
        end

        function malformedRangeShapesAreRejected(tc)
            % SHAPE only. Value validity -- ordering, finiteness -- belongs to
            % rid.roi.Normalization, the single owner of the box invariant,
            % so bounds stays a lookup and the two cannot drift apart.
            rep = rid.rep.Narx(2, 1, "inputDifference", false);
            bad = {[0; 1], [0 1 2], 3, "text", true};
            for iBad = 1:numel(bad)
                roi = struct("u1_k", bad{iBad}, "u1_km1", [0 4], "y_km1", [10 30]);
                tc.verifyError(@() rep.bounds(roi), "rid:rep:invalidRange", ...
                    sprintf("case %d was accepted", iBad));
            end
        end

        function invalidRangeValuesAreRejectedByTheNormalization(tc)
            % The other half of that split: bounds passes an unordered or infinite
            % range through, and Normalization rejects it NAMING THE DIMENSION --
            % which is what the caller needs, since they have a bad declaration and
            % a row index does not say which one.
            rep = rid.rep.Narx(2, 1, "inputDifference", false);
            for badRange = {[5 0], [1 1], [0 Inf], [0 NaN]}
                roi = struct("u1_k", [0 5], "u1_km1", badRange{1}, ...
                             "y_km1", [10 30]);
                [box, dimName] = rep.bounds(roi);         % lookup succeeds
                tc.verifyError(@() rid.roi.Normalization(box, dimName), ...
                    "rid:roi:invalidBox");
                tc.verifySubstring(NarxTest.messageOf( ...
                    @() rid.roi.Normalization(box, dimName)), "u1_km1");
            end
        end

        % --- pastSource, in both settings ----------------------------

        function pastSourceMeasuredUsesTheProcessOutput(tc)
            rep  = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", false, ...
                "pastSource", "measured");
            srg  = rid.surrogate.LinearFirstOrder(0.5, 0.1, 1);
            hist = tc.history();
            hist.x0 = 0;
            Zphys = rep.build(hist, srg);
            tc.verifyEqual(Zphys(:, 3), tc.Y(1:5), "AbsTol", tc.Tol);
        end

        function pastSourceSimulatedUsesTheSurrogateOutput(tc)
            rep  = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", false, ...
                "pastSource", "simulated");
            srg  = rid.surrogate.LinearFirstOrder(0.5, 0.1, 1);
            hist = tc.history();
            hist.x0 = 0;

            yHat = srg.simulate(hist.u, hist.x0);
            Zphys = rep.build(hist, srg);

            tc.verifyEqual(Zphys(:, 3), yHat(1:5), "AbsTol", tc.Tol);
            % ... and the two settings genuinely disagree, so the test above is
            % not passing by coincidence.
            tc.verifyNotEqual(Zphys(:, 3), tc.Y(1:5));
            % The input columns are identical either way: only the OUTPUT
            % coordinate is predicted.
            tc.verifyEqual(Zphys(:, 1:2), [2 1; 4 2; 7 4; 11 7; 16 11], "AbsTol", tc.Tol);
        end

        function measuredWithoutAMeasurementIsAnError(tc)
            % Offline must set pastSource = "simulated" EXPLICITLY: the mode is
            % never inferred from whether a measurement happens to exist.
            rep  = rid.rep.Narx(2, 1, "pastSource", "measured", ...
                "inputDifference", false);
            hist = wellFormedHistory(tc.U, "y", [], "tS", 0.1);
            tc.verifyError(@() rep.build(hist, []), "rid:rep:missingMeasurement");
        end

        function simulatedWithoutAnInitialStateIsAnError(tc)
            % xStart is required, never defaulted; the error names the
            % canonical producer.
            rep  = rid.rep.Narx(2, 1, "pastSource", "simulated", ...
                "inputDifference", false);
            srg  = rid.surrogate.LinearFirstOrder(0.5, 0.1, 1);

            % The history struct NARROWED THIS GUARD and the test says where the halves went.
            % `x0` is now required of EVERY history, so "absent" is structural and
            % never reaches here...
            noField = rmfield(wellFormedHistory(tc.U, "y", tc.Y, "tS", 0.1), "x0");
            tc.verifyError(@() rep.build(noField, srg), "rid:missingHistoryField");

            % ...but an EMPTY x0 is well formed and still hits the pastSource
            % guard, which is the half that only the representation can make.
            hist = wellFormedHistory(tc.U, "y", tc.Y, "tS", 0.1, "x0", zeros(1, 0));
            tc.verifyError(@() rep.build(hist, srg), "rid:rep:missingInitialState");

            % Either way the caller must be told what to DO, or it learns what is
            % wrong and not how to fix it. The pointer to the canonical
            % producer moved into assertHistory with the absent case.
            tc.verifySubstring(NarxTest.messageOf(@() rep.build(hist, srg)), ...
                "steadyState");
            tc.verifySubstring(NarxTest.messageOf(@() rep.build(noField, srg)), ...
                "steadyState");
        end

        function wrongSignalShapesAreRejected(tc)
            rep = rid.rep.Narx(2, 1, "nInputs", 2, "inputDifference", false);
            tc.verifyError(@() rep.build( ...
                wellFormedHistory(tc.U, "y", tc.Y, "tS", 0.1), []), ...
                "rid:rep:dimensionMismatch");
            % u and y disagreeing about how many steps happened is STRUCTURAL:
            % the two signals are sampled together, and no representation has a
            % better answer than any other. It moved to rid:invalidHistory.
            rep1 = rid.rep.Narx(2, 1, "inputDifference", false);
            tc.verifyError(@() rep1.build( ...
                wellFormedHistory(tc.U, "y", tc.Y(1:3), "tS", 0.1), []), ...
                "rid:invalidHistory");
        end

        % --- the feedthrough report ----------------------------------

        function feedthroughNotRepresentedIsReportedNotRefused(tc)
            % Surrogate WITH a direct term, representation WITHOUT u(k): y(k)
            % depends on a coordinate the space omits. Nothing breaks
            % computationally -- the surrogate simulates from the signal, not from
            % the regressor -- so it is reported and the build still succeeds.
            rep  = rid.rep.Narx(2, 1, "nk", 1, "inputDifference", false);
            srg  = rid.surrogate.LinearFirstOrder(0.5, 0.1, 1, "directTerm", 0.4);
            hist = tc.history();

            Zphys = tc.verifyWarning(@() rep.build(hist, srg), ...
                "rid:rep:feedthroughNotRepresented");
            tc.verifyEqual(size(Zphys), [4, 3]);
        end

        function representingTheCurrentInputIsSilentAndIsTheDefault(tc)
            % The reverse combination -- strictly proper surrogate, u(k) in the
            % space -- is the DEFAULT and entirely legitimate: the input
            % coordinates are decision variables, not predictions.
            rep = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", false);
            srgD = rid.surrogate.LinearFirstOrder(0.5, 0.1, 1, "directTerm", 0.4);
            srg0 = rid.surrogate.LinearFirstOrder(0.5, 0.1, 1);
            hist = tc.history();
            tc.verifyWarningFree(@() rep.build(hist, srgD));
            tc.verifyWarningFree(@() rep.build(hist, srg0));

            repNk1 = rid.rep.Narx(2, 1, "nk", 1, "inputDifference", false);
            tc.verifyWarningFree(@() repNk1.build(hist, srg0));
        end

        % --- any representation pairs with any surrogate ---------------------

        function aTwoStateSurrogateDrivesAThreeDimensionalSpace(tc)
            % the surrogate's order and the
            % representation's dimension answer to different limits, and forcing
            % them to match would demand a fifty-dimensional criterion for a
            % fifty-state industrial model. build uses the surrogate ONLY to obtain
            % yHat.
            srg  = MinimalSurrogate();                       % nStates = 2
            rep  = rid.rep.Narx(2, 1, "nk", 0, "inputDifference", true, ...
                "pastSource", "simulated");                  % nDim = 3
            hist = wellFormedHistory(tc.U, "y", [], "x0", [0 0], "tS", 0.1);

            [Zphys, kIndex] = rep.build(hist, srg);
            yHat = srg.simulate(hist.u, hist.x0);
            tc.verifyEqual(size(Zphys), [5 3]);
            tc.verifyEqual(Zphys(:, 3), yHat(1:5), "AbsTol", tc.Tol);
            tc.verifyEqual(kIndex, (2:6).');
        end

        % --- the base-class defaults a NARX representation inherits -----------

        function aNarxRepresentationNeverAsksTheProcessForStates(tc)
            % The joint-space representation contract, the branch it is easiest to get wrong in the other
            % direction: `needsMeasuredStates` is FALSE here even under
            % pastSource = "measured". It is not "hist.x exists" -- a NARX
            % surrogate's state basis is arbitrary, so a measured state is not a
            % valid initial condition for it and anchoring a horizon there would
            % be meaningless. The loop therefore keeps the process contract's one-output call to
            % the process for every NARX run.
            for src = ["measured", "simulated"]
                tc.verifyFalse( ...
                    rid.rep.Narx(2, 1, "pastSource", src).needsMeasuredStates(), ...
                    src);
            end
        end

        function anySurrogateIsCompatibleWithANarxSpace(tc)
            % The base-class `assertCompatible` is a NO-OP, and that is a claim
            % about this family rather than an omission: the coordinates are
            % arithmetic on recorded signals, so any surrogate can supply the
            % predicted ones. A two-state model and a first-order one are both
            % accepted for the same three-dimensional space.
            rep = rid.rep.Narx(2, 1);
            rep.assertCompatible(MinimalSurrogate());
            rep.assertCompatible(rid.surrogate.LinearFirstOrder(0.5, 0.1, 1));
            rep.assertCompatible(MinimalSurrogate(false));   % no nStates at all
            tc.verifyTrue(true);
        end

        % --- describe --------------------------------------------------------

        function describeIsANonEmptyString(tc)
            s = rid.rep.Narx(2, 1).describe();
            tc.verifyClass(s, "string");
            tc.verifyGreaterThan(strlength(s), 0);
        end

    end

    methods (Static, Access = private)
        function roi = declare(names)
            %DECLARE  A valid declaration for an arbitrary name list.
            roi = struct();
            for iName = 1:numel(names)
                roi.(names(iName)) = [-1 1] * iName;
            end
        end

        function msg = messageOf(fh)
            %MESSAGEOF  The message of the error `fh` raises, as a char row.
            %
            %   verifyError checks the identifier; these tests also check that the
            %   message names the offending quantity, which is a specification
            %   requirement in its own right.
            try
                fh();
                msg = '';
            catch err
                msg = err.message;
            end
        end
    end

end
